import { createHash, randomBytes } from "node:crypto";
import { setTimeout as delay } from "node:timers/promises";
import { reportHandoff } from "../analytics.js";
import { closeLoginWindow, openBrowser } from "../browser.js";
import { formatNonProductionEndpointSuffix, getConfig, hasCredentials, saveCredentials, } from "../config.js";
async function verifyToken(serviceUrl, token) {
    try {
        const res = await fetch(`${serviceUrl}/api/plugin/whoami`, {
            headers: { Authorization: `Bearer ${token}` },
        });
        if (!res.ok) {
            return null;
        }
        return (await res.json());
    }
    catch {
        return null;
    }
}
export async function runLogin(platform, pluginVersion, options) {
    const config = getConfig();
    const force = options?.force ?? process.argv.includes("--force");
    if (!force && hasCredentials() && config.apiKey) {
        const who = await verifyToken(config.serviceUrl, config.apiKey);
        if (who) {
            console.log(`Already logged in as ${who.user.email ?? "your account"}${formatNonProductionEndpointSuffix(config.serviceUrl)}.`);
            return;
        }
    }
    const verifier = randomBytes(32).toString("base64url");
    const pkceChallenge = createHash("sha256")
        .update(verifier)
        .digest("base64url");
    const response = await fetch(`${config.serviceUrl}/api/plugin/handoff-tickets`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
            kind: "auth.login",
            pkceChallenge,
            pkceMethod: "S256",
        }),
        signal: AbortSignal.timeout(30_000),
    });
    if (!response.ok) {
        throw new Error(`Could not start login (HTTP ${response.status}).`);
    }
    const ticket = (await response.json());
    const loginWindow = randomBytes(16).toString("hex");
    const signInUrl = `${config.serviceUrl}/plugin/auth/${encodeURIComponent(platform.authPath)}?ticket=${encodeURIComponent(ticket.id)}&loginWindow=${loginWindow}`;
    console.log(`Sign in to Bitfab: ${signInUrl}`);
    const opened = openBrowser(signInUrl);
    if (!opened.launched) {
        console.log("Could not open a browser. Open the sign-in link above to continue.");
    }
    const deadline = Date.now() + 10 * 60 * 1000;
    const pollIntervalMs = Math.max(500, ticket.pollIntervalMs ?? 1500);
    while (Date.now() < deadline) {
        const poll = await fetch(`${config.serviceUrl}/api/plugin/handoff-tickets/${encodeURIComponent(ticket.id)}?verifier=${encodeURIComponent(verifier)}`, {
            signal: AbortSignal.timeout(Math.max(1, Math.min(30_000, deadline - Date.now()))),
        }).catch(() => null);
        if (poll !== null && !poll.ok && poll.status !== 429 && poll.status < 500) {
            throw new Error(`Could not complete login (HTTP ${poll.status}).`);
        }
        const result = poll?.ok
            ? (await poll.json().catch(() => null))
            : null;
        if (result?.status === "completed" && result.data?.token) {
            saveCredentials(result.data.token);
            await closeLoginWindow(signInUrl);
            await reportHandoff(result.data.token, pluginVersion, platform, {
                flow: "auth.login",
                wonBy: "ticket",
                loopbackAvailable: false,
                ticketAvailable: true,
            });
            const who = await verifyToken(config.serviceUrl, result.data.token);
            const message = `Logged in as ${who?.user.email ?? "your account"}${formatNonProductionEndpointSuffix(config.serviceUrl)}.`;
            if (options?.onSuccess) {
                options.onSuccess(message);
            }
            else {
                console.log(message);
            }
            return;
        }
        if (result?.status === "expired") {
            throw new Error("Login expired. Run the login command again.");
        }
        await delay(Math.max(0, Math.min(pollIntervalMs, deadline - Date.now())));
    }
    throw new Error("Login timed out. Run the login command again.");
}
